import express, { Express } from "express";
import { AdvanceOrderUseCase } from "../application/AdvanceOrderUseCase";
import { CancelOrderUseCase } from "../application/CancelOrderUseCase";
import { GetOrderUseCase } from "../application/GetOrderUseCase";
import { GetStockLevelsUseCase } from "../application/GetStockLevelsUseCase";
import { ListOrdersByStateUseCase } from "../application/ListOrdersByStateUseCase";
import { PlaceOrderUseCase } from "../application/PlaceOrderUseCase";
import { StockService } from "../domain/StockService";
import { InMemoryOrderRepository } from "./InMemoryOrderRepository";
import { InMemoryProductRepository } from "./InMemoryProductRepository";
import { OrderController } from "./OrderController";
import { StockController } from "./StockController";
import { UuidIdGenerator } from "./UuidIdGenerator";
import { errorMiddleware } from "./errorMiddleware";
import { seedCatalogue } from "./seedCatalogue";

export function createApp(): Express {
  const orders = new InMemoryOrderRepository();
  const products = new InMemoryProductRepository(seedCatalogue());
  const stock = new StockService(products);

  const orderController = new OrderController(
    new PlaceOrderUseCase(orders, stock, new UuidIdGenerator()),
    new GetOrderUseCase(orders),
    new ListOrdersByStateUseCase(orders),
    new AdvanceOrderUseCase(orders, stock),
    new CancelOrderUseCase(orders, stock),
  );
  const stockController = new StockController(new GetStockLevelsUseCase(products));

  const app = express();
  app.use(express.json());
  app.use("/orders", orderController.router());
  app.use("/products", stockController.router());
  app.use(errorMiddleware);
  return app;
}

